/**
 * Token registry for Celo mainnet + testnet.
 *
 * SECURITY NOTE: every address below was cross-checked against an
 * authoritative source at build time (docs.celo.org's autogenerated
 * token-contracts page, and gooddollar's own docs for G$). None of these
 * were guessed or pattern-matched from memory — in DeFi code, a wrong
 * contract address is the single most dangerous kind of bug, because it
 * fails silently (funds go somewhere, just not where you meant) rather than
 * throwing. If you add a token yourself, pull the address from
 * https://docs.celo.org/token-addresses or the token's own official docs —
 * never from a block explorer search result or a forum post.
 *
 * Sources checked on 2026-07-13:
 *  - https://docs.celo.org/token-addresses  (Mento currencies, USDC, USD₮)
 *  - https://docs.gooddollar.org/for-developers/core-contracts  (G$)
 */

export type TokenSymbol =
  | "CELO"
  | "USDm" // Mento Dollar (this is the same underlying asset historically called cUSD)
  | "EURm" // Mento Euro (formerly cEUR)
  | "BRLm" // Mento Brazilian Real (formerly cREAL)
  | "KESm" // Mento Kenyan Shilling
  | "NGNm" // Mento Nigerian Naira
  | "GHSm" // Mento Ghanaian Cedi
  | "USDC"
  | "USDT"
  | "GOOD_DOLLAR"; // G$ — NOT a Mento token, separate protocol, included because MiniPay/Celo users hold it widely

export interface TokenInfo {
  symbol: TokenSymbol;
  displayName: string;
  decimals: number;
  address: `0x${string}`;
  testnetAddress?: `0x${string}`;
  /** true for Mento-native currencies tradable directly through the Mento Broker */
  isMentoAsset: boolean;
}

