/**
 * Tokens the strategy is allowed to consider trading between. This is a
 * *suggestion* for the off-chain scanner — the real enforcement point is
 * each user's AgentVault.allowedTokens on-chain, which the user controls.
 * Keep this list short at first; every currency you add is another price
 * feed the scanner has to poll and another pair the vault owner has to
 * explicitly allow-list and cap.
 */
export const DEFAULT_STRATEGY_TOKENS: TokenSymbol[] = ["USDm", "KESm", "NGNm", "EURm", "USDC", "USDT", "CELO"];

export function tokenAddress(symbol: TokenSymbol, chainId: number = CELO_MAINNET_CHAIN_ID): `0x${string}` {
  const info = TOKENS[symbol];
  if (chainId === CELO_SEPOLIA_CHAIN_ID && info.testnetAddress) return info.testnetAddress;
  return info.address;
}
